1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	
12	/**
13	 * Step of {@code POST /api/owners} that assigns a stable shared {@code householdId} when the
14	 * request sets {@code sharesHousehold=true}. The id is derived deterministically from the
15	 * normalized lastName and address — the same normalization {@link RequireUniqueHousehold} uses
16	 * to detect a shared household — so every owner joining the same household is given the identical
17	 * identifier. Owners that do not share a household are left with no householdId.
18	 */
19	public class AssignHouseholdId {
20	
21	    public void service(@Val OwnerFieldsDto request, @Val Owner owner) {
22	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
23	            return;
24	        }
25	        owner.setHouseholdId(householdId(request.getLastName(), request.getAddress()));
26	    }
27	
28	    /** Stable identifier for the household sharing {@code lastName} at {@code address}. */
29	    static String householdId(String lastName, String address) {
30	        String key = normalize(lastName) + "|" + AddressNormalizer.normalize(address);
31	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT);
32	    }
33	
34	    /** Trim, collapse internal whitespace runs to a single space, and lower-case for comparison. */
35	    private static String normalize(String value) {
36	        if (value == null) {
37	            return "";
38	        }
39	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
40	    }
41	
42	    private static String sha256Hex(String value) {
43	        try {
44	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
45	            StringBuilder sb = new StringBuilder(digest.length * 2);
46	            for (byte b : digest) {
47	                sb.append(String.format("%02x", b));
48	            }
49	            return sb.toString();
50	        }
51	        catch (NoSuchAlgorithmException e) {
52	            throw new IllegalStateException("SHA-256 not available", e);
53	        }
54	    }
55	}
